def re_arrange_array(arr, n):
    if n <= 0:
        return arr

    write = 0
    for i in range(n):
        if arr[i] < 0:
            if i != write:
                # Shift elements to preserve relative order
                neg = arr[i]
                for j in range(i, write, -1):
                    arr[j] = arr[j - 1]
                arr[write] = neg
            write += 1

    return arr
